<script>
document.addEventListener('DOMContentLoaded', () => {
    const freeBenefitCards = [
        { image: '/assets/images/free-benefits/learning-hub.png', alt: 'Free MSME Learning Hub visual', tagalog: 'Matutong magplano at magpatakbo ng negosyo nang mas maayos.' },
        { image: '/assets/images/free-benefits/chapter-access.png', alt: 'Nationwide Chapter Access visual', tagalog: 'Makipag-ugnayan sa mga negosyante at lider sa buong bansa.' },
        { image: '/assets/images/free-benefits/ka-flame-ai.png', alt: 'Ka-FLAME AI Basic Access visual', tagalog: 'Humingi ng tulong sa AI para sa iyong mga tanong sa negosyo.' },
        { image: '/assets/images/free-benefits/directory-listing.png', alt: 'Free MSME Directory Listing visual', tagalog: 'Ipakita ang iyong negosyo para mas madaling mahanap.' },
        { image: '/assets/images/free-benefits/webinars-meetups.png', alt: 'Free Webinars and Meetups visual', tagalog: 'Matuto, magtanong, at makipagkilala nang libre.' },
        { image: '/assets/images/free-benefits/peer-sourcing.png', alt: 'Peer Sourcing and Bayanihan visual', tagalog: 'Magtulungan para makahanap ng supplier, referral, at oportunidad.' }
    ];
    document.querySelectorAll('#free-benefits article').forEach((card, index) => {
        const benefit = freeBenefitCards[index];
        if (!benefit) return;
        const icon = card.querySelector('.material-symbols-outlined');
        if (icon) icon.outerHTML = `<img class="free-benefit-card-image" src="${benefit.image}" alt="${benefit.alt}" loading="eager" decoding="async">`;
        const description = card.querySelector('p');
        if (description && !card.querySelector('.free-benefit-tagalog')) {
            const translation = document.createElement('p');
            translation.className = 'free-benefit-tagalog';
            translation.textContent = `Tagalog: ${benefit.tagalog}`;
            description.insertAdjacentElement('afterend', translation);
        }
    });

    const hero = document.querySelector('main > section:first-child');
    const grid = hero?.querySelector(':scope > div.relative.mx-auto.grid');
    if (!grid || grid.dataset.heroRebuilt) return;
    grid.dataset.heroRebuilt = 'true';
    grid.classList.add('free-benefits-hero-grid');
    const left = grid.children[0];
    const idPanel = grid.children[1];
    if (!left || !idPanel) return;

    const stats = document.createElement('div');
    stats.className = 'free-benefits-stats';
    stats.innerHTML = '<div class="free-benefits-stat"><strong>78</strong><span>Provincial Hubs</span></div><div class="free-benefits-stat"><strong>100+</strong><span>Ready Templates</span></div><div class="free-benefits-stat"><strong>₱0.00</strong><span>No Hidden Fees</span></div>';
    left.insertBefore(stats, left.querySelector('blockquote'));

    idPanel.className = 'lg:col-span-5';
    left.appendChild(idPanel);

    const plan = document.createElement('aside');
    plan.className = 'free-benefits-plan rounded-2xl bg-white p-5 sm:p-6 lg:col-span-5';
    plan.innerHTML = '<div class="flex items-start justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-widest text-secondary">FLAME PH free</p><h2 class="mt-1 font-headline text-2xl font-extrabold text-on-surface">The ₱0 Free Forever Plan</h2></div><span class="rounded-full bg-surface-container-high px-2 py-1 text-[9px] font-bold uppercase text-primary">Community</span></div><p class="mt-3 text-sm leading-6 text-on-surface-variant">Perfect for aspiring entrepreneurs, start-up owners, home-based sellers, and early-stage businesses who want to begin with zero cost.</p><div class="mt-4 rounded-xl bg-surface-container-low p-4"><div class="flex items-center justify-between"><strong class="font-headline text-2xl text-on-surface">₱0</strong><span class="rounded-full bg-tertiary-fixed px-2 py-1 text-[9px] font-bold text-tertiary-container">No expiry</span></div><p class="mt-1 text-xs text-on-surface-variant">FREE FOREVER plan, no card, no hidden fees, and no obligations.</p></div><h3 class="mt-5 text-sm font-bold text-on-surface">Here’s what you get when you join:</h3><ul class="mt-3 space-y-3 text-xs leading-5 text-on-surface-variant"><li class="flex gap-2"><span class="material-symbols-outlined text-base text-primary">check_circle</span><span><strong class="text-on-surface">Official FLAME PH Digital Membership ID</strong><br>Recognized digital identity for your entrepreneurial journey.</span></li><li class="flex gap-2"><span class="material-symbols-outlined text-base text-primary">check_circle</span><span><strong class="text-on-surface">Full access to community resources</strong><br>Learn, connect, and discover opportunities built for Filipino MSMEs.</span></li><li class="flex gap-2"><span class="material-symbols-outlined text-base text-primary">check_circle</span><span><strong class="text-on-surface">Searchable business directory listing</strong><br>Help customers and partners discover your business.</span></li><li class="flex gap-2"><span class="material-symbols-outlined text-base text-primary">check_circle</span><span><strong class="text-on-surface">Ka-FLAME AI basic access</strong><br>Get practical guidance for your next business step.</span></li><li class="flex gap-2"><span class="material-symbols-outlined text-base text-primary">check_circle</span><span><strong class="text-on-surface">Downloadable MSME resources</strong><br>Use templates, checklists, and learning guides.</span></li></ul><a class="mt-6 inline-flex w-full items-center justify-center rounded-lg bg-secondary px-5 py-3 text-sm font-bold text-white shadow-md hover:bg-secondary-container" href="/membership#registration">Join FLAME PH Free Now →</a><p class="mt-3 text-center text-[10px] leading-4 text-on-surface-variant">No credit card required. Start free today and unlock more support as you grow.</p>';
    const planHeading = plan.querySelector('h3');
    const planList = plan.querySelector('ul');
    if (planHeading) planHeading.textContent = 'Kasama sa iyong Libreng Membership:';
    if (planList) planList.innerHTML = `
        <li class="flex gap-2"><span class="material-symbols-outlined text-base text-secondary">check_circle</span><span><strong class="text-on-surface">Official FLAME PH Digital Membership ID &amp; QR verification</strong><br><em>(Opisyal na digital ID at QR verification para sa lehitimong pagkakakilanlan ng negosyo)</em></span></li>
